UPDATE rental_checklist
SET
  checklist_status='checkout_processing',
  current_checkout_batch_id=#{batch},
  checkout_processing_at=#{now},
  version=version+1,
  updated_at=#{now}
WHERE id=#{id}
  AND owner_user_id=#{actor}
  AND version=#{version}
  AND checklist_status='selecting'
  AND current_owner_guard=#{actor}

mapper.select:
SELECT id, checkout_batch_id, source_checklist_item_id, source_checklist_id, factory_id, factory_name_snapshot, sku_id, prop_name_snapshot, image_url_snapshot, asset_type_snapshot, type_label_snapshot, style_labels_snapshot, quantity, rental_start_date, rental_end_date, rental_days, daily_rent_price_fen, rent_amount_fen, coupon_discount_amount_fen, rent_cash_payable_amount_fen, deposit_unit_amount_fen, deposit_original_amount_fen, deposit_waived_amount_fen, deposit_payable_amount_fen, checkout_batch_transport_snapshot_id, transport_requirement_snapshot, item_snapshot_json, created_at FROM checkout_batch_item_snapshot WHERE checkout_batch_id=#{id}
AND factory_id=#{factoryId}
ORDER BY factory_id, id

SELECT id, checkout_batch_id, factory_id, outbound_service_mode, return_service_mode, factory_address_snapshot, receiver_address_snapshot, outbound_vehicle_tier_id, return_vehicle_tier_id, outbound_distance_meter, return_distance_meter, outbound_guide_min_amount_fen, outbound_guide_max_amount_fen, return_guide_min_amount_fen, return_guide_max_amount_fen, outbound_prepaid_amount_fen, return_prepaid_amount_fen, freight_prepaid_amount_fen, route_pricing_snapshot_json, transport_requirement_snapshot, buyer_remark_snapshot, created_at FROM checkout_batch_transport_snapshot WHERE checkout_batch_id=#{id}
AND factory_id=#{factoryId}
ORDER BY factory_id

mapper.update:
UPDATE rental_checklist
SET
  checklist_status='selecting',
  current_checkout_batch_id=NULL,
  checkout_processing_at=NULL,
  version=version+1,
  updated_at=#{now}
WHERE id=#{id}
  AND current_checkout_batch_id=#{batch}
  AND checklist_status='checkout_processing'

UPDATE checkout_batch
SET
  version=version+1,
  updated_at=#{now}
WHERE id=#{id}
  AND version=#{version}
